B.aSU=new A.kG("\u0639\u064a\u0646\u064a\u0629 \u0623\u0628\u064a \u0630\u0624\u064a\u0628 \u0641\u064a \u0628\u0646\u064a\u0647","\u0623\u0628\u0648 \u0630\u0624\u064a\u0628","\u064a\u064f\u0631\u0648\u0649 \u0623\u0646 \u0623\u0628\u0627 \u0630\u0624\u064a\u0628 \u0647\u0644\u0643 \u0644\u0647 \u062e\u0645\u0633\u0629 \u0628\u0646\u064a\u0646 \u0641\u064a \u0639\u0627\u0645 \u0648\u0627\u062d\u062f \u0628\u0627\u0644\u0637\u0627\u0639\u0648\u0646\u060c \u0648\u0643\u0627\u0646\u0648\u0627 \u0631\u062c\u0627\u0644\u0627\u064b \u0644\u0647\u0645 \u0628\u0623\u0633. \u0641\u0642\u0627\u0644 \u0639\u064a\u0646\u064a\u062a\u0647 \u0627\u0644\u0645\u0634\u0647\u0648\u0631\u0629 \u064a\u0631\u062b\u064a\u0647\u0645 \u0648\u064a\u062a\u0635\u0628\u0651\u0631\u060c \u0648\u0641\u064a\u0647\u0627 \u0623\u0628\u064a\u0627\u062a\u0647 \u0627\u0644\u0633\u0627\u0626\u0631\u0629 \u0641\u064a \u0627\u0644\u0645\u0646\u064a\u0629 \u0648\u0627\u0644\u062a\u062c\u0644\u0651\u062f \u0644\u0644\u0634\u0627\u0645\u062a\u064a\u0646. \u0648\u0639\u062f\u0651\u0647\u0627 \u0627\u0644\u0639\u0644\u0645\u0627\u0621 \u0628\u0627\u0644\u0634\u0639\u0631 \u0645\u0646 \u0623\u062c\u0648\u062f \u0627\u0644\u0645\u0631\u0627\u062b\u064a.","\u0627\u0644\u0634\u0639\u0631 \u0648\u0627\u0644\u0634\u0639\u0631\u0627\u0621 \u0644\u0627\u0628\u0646 \u0642\u062a\u064a\u0628\u0629",null)
